// Generated by Aptly: adds this organization's help center (at /help/) to robots.txt.
// Do not edit; Aptly rewrites or removes this file when the help center setting changes.
const MOUNT = "/help";

export async function onRequest({ request, env }) {
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    return new Response('Method not allowed', { status: 405, headers: { Allow: 'GET, HEAD' } });
  }
  let own = '';
  try {
    const res = await env.ASSETS.fetch(request);
    // A site without robots.txt may answer with its HTML 404 or index page; ignore that.
    if (res.ok && (res.headers.get('content-type') || '').startsWith('text/plain')) {
      own = await res.text();
    }
  } catch (error) {
    own = '';
  }
  const searchRule = `Disallow: ${MOUNT}/search/`;
  const sitemapLine = `Sitemap: ${new URL(request.url).origin}${MOUNT}/sitemap.xml`;
  const base = own.trim();
  const has = line => base.toLowerCase().includes(line.toLowerCase());
  let lines;
  if (!base) {
    lines = ['User-agent: *', searchRule, '', sitemapLine];
  } else {
    // Keep the site's own rules as they are; crawlers merge groups for the same user agent.
    lines = [base];
    if (!has(searchRule)) lines.push('', 'User-agent: *', searchRule);
    if (!has(sitemapLine)) lines.push('', sitemapLine);
  }
  const body = lines.join('\n') + '\n';
  return new Response(request.method === 'HEAD' ? null : body, {
    headers: { 'Content-Type': 'text/plain; charset=utf-8' }
  });
}
